#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "retained_session_scene_candidate.h"
#include "session_timeline_frames_candidate.h"
#include <iostream>
int main(){try{auto g=loadGraph("work/roundtrip-11.dmx");RetainedFilmTrackCandidate index(g,2237);auto frames=sessionTimelineFramesCandidate(g,2237);std::optional<int32_t>gap,sceneLess;for(size_t i=0;i<frames.size();++i){auto tick=frames.tick(i);auto s=index.classify(tick);if(s.state==FilmTimelineStateCandidate::Gap&&!gap)gap=tick;if(s.state==FilmTimelineStateCandidate::SceneLessClip&&!sceneLess)sceneLess=tick;}
 if(!gap||!sceneLess)throw std::runtime_error("blank coverage");RetainedSessionSceneCandidate renderer(std::move(g),2237,{std::filesystem::current_path()},1);FilmTimelineStateCandidate state;
 for(auto pair:std::vector<std::pair<int32_t,FilmTimelineStateCandidate>>{{*gap,FilmTimelineStateCandidate::Gap},{*sceneLess,FilmTimelineStateCandidate::SceneLessClip},{*gap,FilmTimelineStateCandidate::Gap}}){auto frame=renderer.sampleTimeline(pair.first,640,480,state);if(state!=pair.second||!frame.upload.vertices.empty()||!frame.upload.indices.empty()||!frame.upload.materials.empty()||!frame.upload.opaque.empty()||!frame.upload.translucent.empty()||frame.materialInputs.size()!=0||!frame.materialAlpha.empty()||frame.outputWidth!=640||frame.outputHeight!=480||!frame.packedFrameRate)throw std::runtime_error("blank packet");}
 if(renderer.assetCount()||renderer.materialCount())throw std::runtime_error("blank asset load");bool failed=false;try{renderer.sampleTimeline(870833,640,480,state);}catch(const std::runtime_error&e){failed=std::string(e.what()).find("scene model missing:")==0;}if(!failed)throw std::runtime_error("asset failure hidden");auto restored=renderer.sampleTimeline(*gap,640,480,state);if(state!=FilmTimelineStateCandidate::Gap||!restored.upload.vertices.empty())throw std::runtime_error("failure recovery");
 std::cout<<"timeline blank frames passed gap_tick="<<*gap<<" scene_less_tick="<<*sceneLess<<" empty_upload=passed zero_assets=passed missing_asset_propagation=passed gap_after_failure=passed native_blank_policy=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
